// @name Weather demo
// @background #082f49
// @refresh 3600
// A week of (made up) weather: tap a day for its details. The icons are SVG
// inside the UI, colored by the text color (currentColor).
const Sun = ({ size, tone }) => (
  <svg className={`${size} ${tone || 'text-amber-400'}`} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round">
    <circle cx={12} cy={12} r={4} fill="currentColor" />
    <path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4" />
  </svg>
)
const Cloud = ({ size, tone }) => (
  <svg className={`${size} ${tone || 'text-slate-300'}`} viewBox="0 0 24 24">
    <path fill="currentColor" d="M7 18a5 5 0 0 1-.6-9.96A6 6 0 0 1 18 9a4.5 4.5 0 0 1-.5 9z" />
  </svg>
)
const Rain = ({ size, tone }) => (
  <svg className={`${size} ${tone || 'text-sky-400'}`} viewBox="0 0 24 24">
    <path fill={tone ? 'currentColor' : '#cbd5e1'} d="M7 14a5 5 0 0 1-.6-9.96A6 6 0 0 1 18 5a4.5 4.5 0 0 1-.5 9z" />
    <path stroke="currentColor" strokeWidth={2} strokeLinecap="round" d="M8 17l-1 3M12 17l-1 3M16 17l-1 3" />
  </svg>
)
const days = [
  { day: 'Mon', Icon: Sun, hi: 18, lo: 7, text: 'Sunny and still', wind: 6 },
  { day: 'Tue', Icon: Cloud, hi: 15, lo: 8, text: 'Grey, dry', wind: 12 },
  { day: 'Wed', Icon: Rain, hi: 11, lo: 6, rain: 12, text: 'Rain from noon', wind: 22 },
  { day: 'Thu', Icon: Rain, hi: 9, lo: 4, rain: 5, text: 'Showers', wind: 18 },
  { day: 'Fri', Icon: Cloud, hi: 12, lo: 3, text: 'Clouds clearing', wind: 9 },
  { day: 'Sat', Icon: Sun, hi: 16, lo: 5, text: 'Bright, cold start', wind: 7 },
  { day: 'Sun', Icon: Sun, hi: 19, lo: 9, text: 'Warm afternoon', wind: 5 },
]
// The picked day, and a flag per day for its tile. They are signals: a tap
// runs only the card and the two tiles that read them, not get().
const pick = signal(0)
const picked = days.map((_, i) => signal(i === 0))
const show = (i) => {
  pick.value = i
  picked.forEach((on, j) => { on.value = j === i })
}

// The picked day outlives the render: a board may start each render with a
// fresh module, and a frame rendered on its server does, at every tap.
let recalled = false
const recallDay = () => {
  if (recalled) return
  recalled = true
  show(frameos.recall('day') ?? pick.peek())
}
const choose = (i) => {
  show(i)
  frameos.remember('day', i)
}

// High contrast where the panel shows no color (black and white, greys), or
// when the scene's Contrast setting asks for it.
const highContrast = (app) => {
  const mode = app.state.contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && app.frame.color === false)
}

// The icons keep their own colors in the color look (tone null) and take
// black, or white on the picked day, in high contrast.
const THEMES = {
  color: {
    page: 'bg-sky-950 text-white',
    card: 'bg-white/10',
    label: 'text-sky-200',
    muted: 'text-slate-300',
    tile: 'bg-white/5 active:bg-white/15',
    tileOn: 'bg-white/25',
    dayText: 'text-slate-300',
    lowText: 'text-slate-400',
    icon: null,
    iconOn: null,
  },
  high: {
    page: 'bg-white text-black',
    card: 'bg-white border-2 border-black',
    label: 'text-black',
    muted: 'text-black',
    tile: 'bg-white border-2 border-black',
    tileOn: 'bg-black text-white border-2 border-black',
    dayText: '',
    lowText: '',
    icon: 'text-black',
    iconOn: 'text-white',
  },
}

// Three sizes: compact on a small screen (a watch, a 2.8" panel, a short
// strip), the one made for 480 to 800 px, and twice that where the canvas is
// over 1150 px on its shorter side (a 13.3" e-paper at scale 1), whose card
// and days would otherwise hold small words in a lot of room. `pad` and
// `padHigh` are the card's padding, the latter inside its 2 px border.
const SIZES = {
  compact: {
    page: 'gap-2 p-[10px]', pad: 'p-3', padHigh: 'p-[10px]', card: 'gap-3 rounded-2xl', icon: 'w-12 h-12',
    label: 'text-sm', temp: 'text-4xl', text: 'text-sm leading-tight', side: 'text-xs gap-[2px]',
    week: 'gap-1', tile: 'gap-1 rounded-xl', day: 'text-xs', tileIcon: 'w-6 h-6', hi: 'text-sm', lo: 'text-xs',
    row: 'gap-2 px-2 rounded-xl', rowDay: 'w-10 text-sm', rowText: 'text-sm', rowLo: 'w-8 text-xs',
  },
  normal: {
    page: 'gap-4 p-5', pad: 'p-5', padHigh: 'p-[18px]', card: 'gap-5 rounded-3xl', icon: 'w-24 h-24',
    label: 'text-lg', temp: 'text-6xl', text: '', side: 'text-sm gap-1',
    week: 'gap-2', tile: 'gap-2 rounded-2xl', day: 'text-sm', tileIcon: 'w-9 h-9', hi: 'text-lg', lo: 'text-sm',
    row: 'gap-4 px-4 rounded-2xl', rowDay: 'w-12 text-lg', rowText: 'text-base', rowLo: 'w-10 text-sm',
  },
  large: {
    page: 'gap-8 p-10', pad: 'p-10', padHigh: 'p-[38px]', card: 'gap-10 rounded-[48px]', icon: 'w-48 h-48',
    label: 'text-4xl', temp: 'text-[120px] leading-none', text: 'text-[32px] leading-10', side: 'text-[28px] leading-10 gap-2',
    week: 'gap-4', tile: 'gap-4 rounded-[32px]', day: 'text-[28px] leading-10', tileIcon: 'w-[72px] h-[72px]', hi: 'text-4xl', lo: 'text-[28px] leading-10',
    row: 'gap-8 px-8 rounded-[32px]', rowDay: 'w-24 text-4xl', rowText: 'text-[32px] leading-10', rowLo: 'w-20 text-[28px] leading-10',
  },
}

// The picked day's details. Where the card is narrow (a watch) the low, the
// wind and the rain go in a line under it.
const Card = memo(({ t, s, narrow }) => {
  const d = days[pick.value]
  const details = [
    <span>{`Low ${d.lo}°`}</span>,
    <span>{`Wind ${d.wind} km/h`}</span>,
    <span>{d.rain ? `Rain ${d.rain} mm` : 'No rain'}</span>,
  ]
  return (
    <div className={`flex flex-col gap-2 ${s.card} ${t === THEMES.high ? s.padHigh : s.pad} ${t.card}`}>
      <div className={`flex items-center ${s.card}`}>
        {d.Icon({ size: s.icon, tone: t.icon })}
        <div className="flex flex-col flex-1">
          <span className={`${s.label} ${t.label}`}>{pick.value === 0 ? 'Today' : d.day}</span>
          <span className={`${s.temp} font-bold`}>{`${d.hi}°`}</span>
          <span className={`${s.text} ${t.muted}`}>{d.text}</span>
        </div>
        {narrow ? null : <div className={`flex flex-col items-end whitespace-nowrap ${s.side} ${t.muted}`}>{details}</div>}
      </div>
      {narrow ? <div className={`flex justify-between whitespace-nowrap ${s.side} ${t.muted}`}>{details}</div> : null}
    </div>
  )
})

const Tile = memo(({ i, t, s }) => {
  const x = days[i]
  const on = picked[i].value
  return (
    <div className={`flex flex-col items-center justify-center ${s.tile} ${on ? t.tileOn : t.tile}`}
      onClick={() => choose(i)}>
      <span className={`${s.day} ${on ? 'font-bold' : t.dayText}`}>{x.day}</span>
      {x.Icon({ size: s.tileIcon, tone: on ? t.iconOn : t.icon })}
      <span className={`${s.hi} font-semibold`}>{`${x.hi}°`}</span>
      <span className={`${s.lo} ${t.lowText}`}>{`${x.lo}°`}</span>
    </div>
  )
})

// On a screen taller than wide the week is seven rows, each with its words.
const Row = memo(({ i, t, s }) => {
  const x = days[i]
  const on = picked[i].value
  return (
    <div className={`flex-1 flex items-center ${s.row} ${on ? t.tileOn : t.tile}`}
      onClick={() => choose(i)}>
      <span className={`${s.rowDay} ${on ? 'font-bold' : t.dayText}`}>{x.day}</span>
      {x.Icon({ size: s.tileIcon, tone: on ? t.iconOn : t.icon })}
      <span className={`flex-1 min-w-0 truncate ${s.rowText} ${on ? '' : t.dayText}`}>{x.text}</span>
      <span className={`${s.hi} font-semibold`}>{`${x.hi}°`}</span>
      <span className={`${s.rowLo} text-right ${t.lowText}`}>{`${x.lo}°`}</span>
    </div>
  )
})

// On a round panel the week goes around the rim like the hours of a clock,
// and the picked day's details are in the middle.
const RoundCard = memo(({ t, px }) => {
  const d = days[pick.value]
  return (
    <div className="flex flex-col items-center justify-center w-full h-full">
      <span className={`text-[${px(18)}px] ${t.label}`}>{pick.value === 0 ? 'Today' : d.day}</span>
      <div className={`flex items-center gap-[${px(8)}px]`}>
        {d.Icon({ size: `w-[${px(60)}px] h-[${px(60)}px]`, tone: t.icon })}
        <span className={`text-[${px(56)}px] leading-none font-bold`}>{`${d.hi}°`}</span>
      </div>
      <span className={`text-[${px(17)}px] mt-[${px(4)}px]`}>{d.text}</span>
      <span className={`text-[${px(14)}px] ${t.muted}`}>{`Low ${d.lo}° · Wind ${d.wind} km/h`}</span>
      <span className={`text-[${px(14)}px] ${t.muted}`}>{d.rain ? `Rain ${d.rain} mm` : 'No rain'}</span>
    </div>
  )
})
const RoundTile = memo(({ i, t, px, d: size, x, y }) => {
  const day = days[i]
  const on = picked[i].value
  return (
    <div className={`absolute left-[${x}px] top-[${y}px] w-[${size}px] h-[${size}px] rounded-full flex flex-col items-center justify-center ${on ? t.tileOn : t.tile}`}
      onClick={() => choose(i)}>
      <span className={`text-[${px(14)}px] leading-tight ${on ? 'font-bold' : t.dayText}`}>{day.day}</span>
      {day.Icon({ size: `w-[${px(24)}px] h-[${px(24)}px]`, tone: on ? t.iconOn : t.icon })}
      <span className={`text-[${px(16)}px] leading-tight font-semibold`}>{`${day.hi}°`}</span>
    </div>
  )
})
const getRound = (context, t) => {
  const W = context.imageWidth, H = context.imageHeight
  const size = Math.min(W, H), r = size / 2
  const k = r / 240
  const px = (n) => Math.max(n >= 14 ? 14 : 1, Math.round(n * k))
  const tile = Math.round(r * 0.37)
  const ring = r - Math.max(12, px(12)) - tile / 2
  const inner = Math.round((ring - tile / 2) * 1.6)
  return (
    <div className={`relative w-[${W}px] h-[${H}px] ${t.page}`}>
      <div className={`absolute left-[${(W - size) >> 1}px] top-[${(H - size) >> 1}px] w-[${size}px] h-[${size}px]`}>
        <div className={`absolute left-[${Math.round(r - inner / 2)}px] top-[${Math.round(r - inner / 2)}px] w-[${inner}px] h-[${inner}px]`}>
          <RoundCard t={t} px={px} />
        </div>
        {days.map((_, i) => {
          const a = (i / days.length) * 2 * Math.PI
          return <RoundTile i={i} t={t} px={px} d={tile}
            x={Math.round(r + ring * Math.sin(a) - tile / 2)} y={Math.round(r - ring * Math.cos(a) - tile / 2)} />
        })}
      </div>
    </div>
  )
}

export function get(app, context) {
  recallDay()
  if (context?.round === true) return getRound(context, highContrast(app) ? THEMES.high : THEMES.color)
  const t = highContrast(app) ? THEMES.high : THEMES.color
  const W = context?.imageWidth ?? app.frame.width
  const H = context?.imageHeight ?? app.frame.height
  // At full size the card needs about 380 px across and the week 330 px down.
  const s = Math.min(W, H) >= 1150 ? SIZES.large : W < 380 || H < 330 ? SIZES.compact : SIZES.normal
  return (
    <div className={`flex flex-col ${s.page} ${t.page}`}>
      <Card t={t} s={s} narrow={W < 300} />
      {H >= W * 1.25 ? (
        <div className={`flex-1 flex flex-col ${s.week}`}>
          {days.map((_, i) => <Row i={i} t={t} s={s} />)}
        </div>
      ) : (
        <div className={`flex-1 grid grid-cols-7 ${s.week}`}>
          {days.map((_, i) => <Tile i={i} t={t} s={s} />)}
        </div>
      )}
    </div>
  )
}
